// Builds src/profiles/sourceTables.ts from the section tables in data/sources, as published by
// their authors (see data/sources/README.md). Run with `pnpm catalog`; a test fails while the
// generated file is out of date.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const SOURCES_DIR = join(root, 'data', 'sources');
export const OUTPUT_FILE = join(root, 'src', 'profiles', 'sourceTables.ts');

type Row = Record<string, string>;

function readCsv(file: string): Row[] {
  const lines = readFileSync(file, 'utf8')
    .split(/\r?\n/)
    .filter((line) => line.length > 0 && !line.startsWith('#'));
  const header = lines[0].split(',');
  return lines.slice(1).map((line) => {
    const cells = line.split(',');
    if (cells.length !== header.length) throw new Error(`${file}: "${line}" has ${cells.length} cells, the header ${header.length}`);
    return Object.fromEntries(header.map((name, i) => [name, cells[i]]));
  });
}

function num(row: Row, column: string, file: string): number {
  const value = Number(row[column]);
  if (row[column] === '' || !Number.isFinite(value)) throw new Error(`${file}: ${column} of ${JSON.stringify(row)} is not a number`);
  return value;
}

/** Ascending by the numbers in the size: "80" < "100", "127x76x13" < "152x89x16". */
function bySize(a: { size: string }, b: { size: string }): number {
  const x = a.size.split('x').map(Number);
  const y = b.size.split('x').map(Number);
  for (let i = 0; i < Math.max(x.length, y.length); i++) if (x[i] !== y[i]) return (x[i] ?? 0) - (y[i] ?? 0);
  return 0;
}

/** "IPE 80" -> "80"; the family must match. */
function sizeOf(designation: string, family: string, file: string): string {
  const [prefix, size] = designation.split(' ');
  if (prefix !== family || !size) throw new Error(`${file}: designation "${designation}" is not "${family} <size>"`);
  return size;
}

function ulmewixParallel(family: string) {
  const file = join(SOURCES_DIR, 'ulmewix', `${family}.csv`);
  return readCsv(file)
    .map((r) => ({
      size: sizeOf(r.designation, family, file),
      h: num(r, 'h', file),
      b: num(r, 'b', file),
      tw: num(r, 'tw', file),
      tf: num(r, 'tf', file),
      r: num(r, 'r', file),
    }))
    .sort(bySize);
}

function ulmewixTapered(family: string) {
  const file = join(SOURCES_DIR, 'ulmewix', `${family}.csv`);
  return readCsv(file)
    .map((r) => ({
      size: sizeOf(r.designation, family, file),
      h: num(r, 'h', file),
      b: num(r, 'b', file),
      tw: num(r, 'tw', file),
      tf: num(r, 'tf', file),
      r1: num(r, 'r1', file),
      r2: num(r, 'r2', file),
      slopePct: num(r, 'slope_pct', file),
      xTf: num(r, 'x_tf', file),
    }))
    .sort(bySize);
}

/** Koyda gives the BS EN 10365 root radius and, for UB/UC sizes where it differs, the BS 4-1:2005 one, which wins. */
function koyda(name: string) {
  const file = join(SOURCES_DIR, 'koyda', `${name}.csv`);
  return readCsv(file)
    .map((r) => ({
      size: r.designation,
      h: num(r, 'h_mm', file),
      b: num(r, 'b_mm', file),
      tw: num(r, 't_w_mm', file),
      tf: num(r, 't_f_mm', file),
      r: num(r, r.r_bs4_2005_mm ? 'r_bs4_2005_mm' : 'r_mm', file),
    }))
    .sort(bySize);
}

function table(name: string, type: string, doc: string, rows: object[]): string {
  const literal = (v: unknown) => (typeof v === 'string' ? `'${v}'` : String(v));
  const body = rows.map((row) => `  { ${Object.entries(row).map(([k, v]) => `${k}: ${literal(v)}`).join(', ')} },`);
  return [`/** ${doc} */`, `export const ${name}: readonly ${type}[] = [`, ...body, '];', ''].join('\n');
}

export function renderSourceTables(): string {
  const ulmewix = 'ulmewix/Steel_Section_Database, Adam Koudelka, MIT';
  const koydaCredit = 'Koyda Ltd steel section tables (www.koyda.com), CC BY 4.0';
  return [
    '// Generated by scripts/build-catalog.ts from data/sources. Do not edit; run `pnpm catalog`.',
    '// Section dimensions are copied from openly licensed tables and credited in NOTICE.md.',
    '',
    '/** Parallel-flange section, millimetres: r is the root radius. */',
    'export interface ParallelFlangeRow { size: string; h: number; b: number; tw: number; tf: number; r: number }',
    '',
    '/** Taper-flange section, millimetres: r1 root and r2 toe radius, tf measured xTf from the flange tip. */',
    'export interface TaperFlangeRow {',
    '  size: string; h: number; b: number; tw: number; tf: number; r1: number; r2: number; slopePct: number; xTf: number;',
    '}',
    '',
    table('IPE_ROWS', 'ParallelFlangeRow', `IPE (EN 10365). ${ulmewix}.`, ulmewixParallel('IPE')),
    table('IPN_ROWS', 'TaperFlangeRow', `IPN (EN 10365). ${ulmewix}.`, ulmewixTapered('IPN')),
    table('HEA_ROWS', 'ParallelFlangeRow', `HEA (EN 10365). ${ulmewix}.`, ulmewixParallel('HEA')),
    table('HEB_ROWS', 'ParallelFlangeRow', `HEB (EN 10365). ${ulmewix}.`, ulmewixParallel('HEB')),
    table('HEM_ROWS', 'ParallelFlangeRow', `HEM (EN 10365). ${ulmewix}.`, ulmewixParallel('HEM')),
    table('UPN_ROWS', 'TaperFlangeRow', `UPN (EN 10365). ${ulmewix}.`, ulmewixTapered('UPN')),
    table('UPE_ROWS', 'ParallelFlangeRow', `UPE (EN 10365). ${ulmewix}.`, ulmewixParallel('UPE')),
    table('UB_ROWS', 'ParallelFlangeRow', `UB universal beams (BS 4-1). ${koydaCredit}.`, koyda('universal-beams')),
    table('UC_ROWS', 'ParallelFlangeRow', `UC universal columns (BS 4-1). ${koydaCredit}.`, koyda('universal-columns')),
    table('PFC_ROWS', 'ParallelFlangeRow', `PFC parallel flange channels (BS 4-1). ${koydaCredit}.`, koyda('parallel-flange-channels')),
  ].join('\n');
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  writeFileSync(OUTPUT_FILE, renderSourceTables());
  console.log(`wrote ${OUTPUT_FILE}`);
}
